import React, { useState, useEffect, useCallback } from "react";
import { securedAxiosInstance } from "../../../axiosConfig";
import {
  Badge,
  Button,
  Card,
  Spinner,
  Modal,
  Form,
  Alert,
  Table,
  Row,
  Col,
} from "@themesberg/react-bootstrap";
import toast from "react-hot-toast";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faFilePdf,
  faEye,
  faUpload,
  faDownload,
  faTrash,
} from "@fortawesome/free-solid-svg-icons";
import { ConfirmDialog } from "../../../components/ConfirmDialog";

export default function AllForms() {
  const [forms, setForms] = useState([]);
  const [loadingForms, setLoadingForms] = useState(true);

  const [showUploadModal, setShowUploadModal] = useState(false);
  const [selectedForm, setSelectedForm] = useState(null);
  const [selectedFile, setSelectedFile] = useState(null);
  const [isCheckboxChecked, setIsCheckboxChecked] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [uploadError, setUploadError] = useState("");

  const [uploads, setUploads] = useState([]);
  const [showDeleteDialog, setShowDeleteDialog] = useState(false);
  const [deleteUploadId, setDeleteUploadId] = useState(null);

  const [pdfUrl, setPdfUrl] = useState("");
  const [showPdfModal, setShowPdfModal] = useState(false);

  const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);

  useEffect(() => {
    const fetchForms = async () => {
      try {
        const response = await securedAxiosInstance.get(
          "/forms?is_active=true&_sort=createdAt:desc"
        );
        setForms(response.data);
      } catch (error) {
        console.error("Failed to fetch forms:", error);
      } finally {
        setLoadingForms(false);
      }
    };

    const fetchUploads = async () => {
      try {
        const response = await securedAxiosInstance.get(
          "/form-uploads/me?_sort=createdAt:desc"
        );
        const sorted = response.data.sort(
          (a, b) => new Date(b.createdAt) - new Date(a.createdAt)
        );
        setUploads(sorted);
      } catch (error) {
        console.error("Failed to fetch uploads:", error);
      }
    };

    const handleResize = () => {
      setIsMobile(window.innerWidth <= 768);
    };

    window.addEventListener("resize", handleResize);

    fetchForms();
    fetchUploads();

    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const handleOpenModal = (form) => {
    setSelectedForm(form);
    setSelectedFile(null);
    setIsCheckboxChecked(false);
    setUploadError("");
    setShowUploadModal(true);
  };

  const handleUpload = async () => {
    if (!selectedFile) {
      setUploadError("Please select a PDF file.");
      return;
    }
    if (!selectedFile.name.toLowerCase().endsWith(".pdf")) {
      setUploadError("Only PDF files are allowed.");
      return;
    }
    if (!isCheckboxChecked) {
      setUploadError("You must confirm the information is correct.");
      return;
    }

    setUploading(true);
    setUploadError("");

    try {
      const formData = new FormData();
      formData.append("data", JSON.stringify({ formId: selectedForm._id }));
      formData.append("files.file", selectedFile);

      const response = await securedAxiosInstance.post(
        "/form-uploads/upload",
        formData,
        { headers: { "Content-Type": "multipart/form-data" } }
      );

      if (response.status === 200 || response.status === 201) {
        toast.success("File uploaded successfully!");
        setShowUploadModal(false);
        const uploadsRes = await securedAxiosInstance.get(
          "/form-uploads/me?_sort=createdAt:desc"
        );
        const sorted = uploadsRes.data.sort(
          (a, b) => new Date(b.createdAt) - new Date(a.createdAt)
        );
        setUploads(sorted);
      }
    } catch (error) {
      console.error("Upload failed:", error);
      const msg =
        error?.response?.data?.error?.message ||
        "Upload failed. Please try again.";
      setUploadError(msg);
      toast.error(msg);
    } finally {
      setUploading(false);
    }
  };

  const renderStatusBadge = (status) => {
    let color = "secondary";
    if (status === "REJECTED") color = "danger";
    if (status === "ACCEPTED") color = "success";
    if (status === "PENDING") color = "warning";
    const statusText = {
      REJECTED: "Rejected",
      ACCEPTED: "Accepted",
      PENDING: "Under Review",
    };
    return (
      <Badge bg={color} className="px-2 py-1 text-uppercase">
        {statusText[status] || "N/A"}
      </Badge>
    );
  };

  const getUploadsForForm = (formId) =>
    uploads.filter((u) => u.form?._id === formId);

  const canUploadForm = (formId) => {
    const related = getUploadsForForm(formId);
    if (related.length === 0) return true;
    return !related.some(
      (u) => u.status === "ACCEPTED" || u.status === "PENDING"
    );
  };

  const handleViewPDF = useCallback(
    (url) => {
      if (isMobile) {
        window.open(url, "_blank");
      } else {
        setPdfUrl(url);
        setShowPdfModal(true);
      }
    },
    [isMobile]
  );

  const handleDeleteUpload = useCallback((uploadId) => {
    setDeleteUploadId(uploadId);
    setShowDeleteDialog(true);
  }, []);

  const handleDelete = async () => {
    if (!deleteUploadId) return;
    setShowDeleteDialog(false);
    try {
      await securedAxiosInstance.delete(`/form-uploads/${deleteUploadId}/self`);
      toast.success("Upload deleted successfully!");
      setUploads((prev) => prev.filter((u) => u._id !== deleteUploadId));
    } catch (error) {
      console.error("Delete failed:", error);
      const msg =
        error?.response?.data?.error?.message ||
        "Delete failed. Please try again.";
      setShowDeleteDialog(false);
      toast.error(msg);
    } finally {
      setDeleteUploadId(null);
    }
  };

  if (loadingForms) {
    return (
      <div className="text-center my-5">
        <Spinner animation="border" role="status" />
        <div>Loading Forms...</div>
      </div>
    );
  }

  return (
    <div className="container py-4">
      <div
        className="alert alert-warning mb-4 text-sm md:text-base px-3 py-2 pt-4"
        role="alert"
      >
        <div className="space-y-4">
          <div className="space-y-2">
            <h4 className="text-xs font-medium mb-1 uppercase tracking-wide">
              1. Download, Print, and Upload in PDF Format
            </h4>
            <p>
              Students must download the preplacement undertaking form, print it
              clearly, get it physically signed by both parents and the student,
              and then upload a scanned copy in PDF format only. Submission of
              this undertaking is compulsory to be eligible for participating in
              the campus placement process.
            </p>
          </div>

          <div className="space-y-2">
            <h4 className="text-xs font-medium mb-1 uppercase tracking-wide">
              2. Use Clear Handwriting and Original Signatures Only
            </h4>
            <ul className="list-disc pl-5 space-y-1">
              <li>
                Fill in all fields (Name, Roll Number, Branch, etc.) using
                capital letters and blue or black ink.
              </li>
              <li>Avoid overwriting or correction fluid.</li>
              <li>
                Only original handwritten signatures of the student and parents
                will be accepted.
              </li>
              <li>
                Digital signatures or typed names will not be considered valid.
              </li>
            </ul>
          </div>

          <div className="space-y-2">
            <h4 className="text-xs font-medium mb-1 uppercase tracking-wide">
              3. Fill All Details Accurately
            </h4>
            <p>
              Ensure that all personal and academic details match your official
              university records. Double-check for spelling and numerical
              accuracy.
            </p>
          </div>

          <div className="space-y-2">
            <h4 className="text-xs font-medium mb-1 uppercase tracking-wide">
              4. Avoid Short Forms or Abbreviations
            </h4>
            <p>
              Write full names and addresses—no abbreviations or initials—to
              avoid any confusion or rejection.
            </p>
          </div>

          <div className="space-y-2">
            <h4 className="text-xs font-medium mb-1 uppercase tracking-wide">
              5. Read the Undertaking Carefully Before Signing
            </h4>
            <p>
              Go through all the terms and responsibilities mentioned in the
              form before signing. Signing implies your agreement to the
              university&#39;s placement policy.
            </p>
          </div>

          <div className="space-y-2">
            <h4 className="text-xs font-medium mb-1 uppercase tracking-wide">
              6. Discuss and Sign with Parents/Guardians
            </h4>
            <p>
              The undertaking must be signed by both parents (father and mother)
              along with the student. Ensure they are informed and agree to the
              terms before signing.
            </p>
          </div>
        </div>
      </div>

      <div>
        <h4>Available Forms</h4>

        <div className="mb-4">
          {forms.map((form) => {
            const relatedUploads = getUploadsForForm(form._id);
            const hasAnyUpload = relatedUploads.length > 0;
            const hideUpload = !canUploadForm(form._id);

            const showRequiredBadge = form.is_blocking && !hideUpload;

            let statusBadge = null;
            if (hasAnyUpload) {
              if (relatedUploads.some((u) => u.status === "ACCEPTED")) {
                statusBadge = renderStatusBadge("ACCEPTED");
              } else if (relatedUploads.some((u) => u.status === "PENDING")) {
                statusBadge = renderStatusBadge("PENDING");
              } else if (relatedUploads.some((u) => u.status === "REJECTED")) {
                statusBadge = renderStatusBadge("REJECTED");
              }
            }

            return (
              <Card
                key={form._id}
                className="mb-3 p-3 shadow-sm border border-2"
              >
                <div className="d-flex justify-content-between align-items-center">
                  <div>
                    <strong>{form.name}</strong>{" "}
                    {showRequiredBadge && (
                      <Badge bg="danger" className="ms-2 px-2 py-1">
                        Required
                      </Badge>
                    )}
                    {statusBadge && <span className="ms-2">{statusBadge}</span>}
                  </div>

                  <div className="d-flex gap-2 align-items-center">
                    {!hideUpload && (
                      <Button
                        variant="primary"
                        size="sm"
                        onClick={() => handleOpenModal(form)}
                      >
                        <FontAwesomeIcon icon={faUpload} />{" "}
                        {!isMobile && " Upload"}
                      </Button>
                    )}
                    <Button
                      variant="outline-primary"
                      size="sm"
                      onClick={() => handleViewPDF(form.file?.url)}
                    >
                      <FontAwesomeIcon icon={faFilePdf} />{" "}
                      {!isMobile && " View"}
                    </Button>
                  </div>
                </div>
              </Card>
            );
          })}
        </div>
      </div>

      <Modal
        show={showUploadModal}
        onHide={() => setShowUploadModal(false)}
        centered
        size="lg"
      >
        <Modal.Header closeButton>
          <Modal.Title>Upload for: {selectedForm?.name}</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form.Group className="mb-3">
            <Form.Label>Select PDF File</Form.Label>
            <Form.Control
              type="file"
              accept="application/pdf"
              onChange={(e) => setSelectedFile(e.target.files[0])}
            />
          </Form.Group>

          <Form.Check
            type="checkbox"
            label="I confirm the information provided is correct and true as per my knowledge."
            checked={isCheckboxChecked}
            onChange={(e) => setIsCheckboxChecked(e.target.checked)}
          />

          {uploadError && (
            <Alert variant="danger" className="mt-3">
              {uploadError}
            </Alert>
          )}

          {uploading && (
            <Alert variant="info" className="mt-3">
              Uploading, please wait...
            </Alert>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button
            variant="secondary"
            onClick={() => setShowUploadModal(false)}
            disabled={uploading}
          >
            Cancel
          </Button>
          <Button variant="primary" onClick={handleUpload} disabled={uploading}>
            {uploading ? "Uploading..." : "Upload"}
          </Button>
        </Modal.Footer>
      </Modal>

      <Modal
        show={showPdfModal}
        onHide={() => setShowPdfModal(false)}
        size="xl"
        centered
      >
        <Modal.Header closeButton>
          <Modal.Title>View PDF</Modal.Title>
        </Modal.Header>
        <Modal.Body style={{ height: "80vh" }}>
          {pdfUrl ? (
            <iframe
              src={pdfUrl}
              style={{ width: "100%", height: "100%", border: "none" }}
              title="PDF Viewer"
            ></iframe>
          ) : (
            <Alert variant="warning">No PDF available.</Alert>
          )}
        </Modal.Body>
      </Modal>

      <h5 className="mt-5">Your Uploaded Forms</h5>

      <div className="d-none d-md-block">
        {uploads.length === 0 ? (
          <Alert variant="secondary">No uploads yet.</Alert>
        ) : (
          <Table bordered hover responsive>
            <thead>
              <tr>
                <th>Form</th>
                <th>Status</th>
                <th>Message</th>
                <th>Uploaded At</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {uploads.map((u) => (
                <tr key={u._id}>
                  <td>{u.form?.name || "Unknown"}</td>
                  <td>{renderStatusBadge(u.status)}</td>
                  <td
                    className="text-break"
                    style={{
                      minWidth: "260px",
                      maxWidth: "260px",
                      whiteSpace: "pre-wrap",
                      wordBreak: "break-word",
                    }}
                  >
                    {u.message || "No message"}
                  </td>
                  <td>{new Date(u.createdAt).toLocaleString()}</td>
                  <td>
                    <Button
                      variant="outline-primary"
                      size="sm"
                      onClick={() => handleViewPDF(u.file?.url)}
                      className="me-2"
                    >
                      <FontAwesomeIcon icon={faEye} /> View
                    </Button>
                    {u.status === "PENDING" && (
                      <Button
                        variant="outline-danger"
                        size="sm"
                        onClick={() => handleDeleteUpload(u._id)}
                      >
                        <FontAwesomeIcon icon={faTrash} /> Delete
                      </Button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </Table>
        )}
      </div>

      <div className="d-block d-md-none">
        {uploads.length === 0 ? (
          <Alert variant="secondary">No uploads yet.</Alert>
        ) : (
          <Row xs={1} className="g-3">
            {uploads.map((u) => (
              <Col key={u._id}>
                <Card className="p-3 shadow-sm">
                  <h6>{u.form?.name || "Unknown Form"}</h6>
                  <div className="mb-2">{renderStatusBadge(u.status)}</div>
                  <div className="mb-2">
                    <strong>Message:</strong>{" "}
                    <span
                      className="text-break"
                      style={{
                        minWidth: "200px",
                        maxWidth: "200px",
                        whiteSpace: "pre-wrap",
                        wordBreak: "break-word",
                      }}
                    >
                      {u.message || "No message"}
                    </span>
                  </div>
                  <div className="mb-2">
                    <small>
                      Uploaded: {new Date(u.createdAt).toLocaleString()}
                    </small>
                  </div>
                  <div className="d-flex gap-2">
                    <Button
                      variant="outline-primary"
                      size="sm"
                      onClick={() => handleViewPDF(u.file?.url)}
                    >
                      <FontAwesomeIcon icon={faEye} />
                    </Button>
                    {u.status === "PENDING" && (
                      <Button
                        variant="outline-danger"
                        size="sm"
                        onClick={() => handleDeleteUpload(u._id)}
                      >
                        <FontAwesomeIcon icon={faTrash} />
                      </Button>
                    )}
                  </div>
                </Card>
              </Col>
            ))}
          </Row>
        )}
      </div>
      <ConfirmDialog
        show={showDeleteDialog}
        title="Delete Record"
        message="This action cannot be undone."
        requiredPhrase="DELETE"
        onCancel={() => setShowDeleteDialog(false)}
        onConfirm={handleDelete}
      />
    </div>
  );
}
